from typing import List

class Solution:
    def advantageCount(self, nums1: List[int], nums2: List[int]) -> List[int]:
        nums1.sort()
        order = sorted(range(len(nums2)), key=lambda i: nums2[i])
        ans = [0] * len(nums1)
        lo, hi = 0, len(nums2) - 1
        for x in nums1:
            if x > nums2[order[lo]]:
                ans[order[lo]] = x
                lo += 1
            else:
                ans[order[hi]] = x
                hi -= 1
        return ans

class Solution {
public:
    vector<int> advantageCount(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        sort(nums1.begin(), nums1.end());
        vector<int> order(n);
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b) {
            return nums2[a] < nums2[b];
        });
        vector<int> ans(n);
        int lo = 0, hi = n - 1;
        for (int x : nums1) {
            if (x > nums2[order[lo]]) {
                ans[order[lo++]] = x;
            } else {
                ans[order[hi--]] = x;
            }
        }
        return ans;
    }
};

class Solution {
    public int[] advantageCount(int[] nums1, int[] nums2) {
        int n = nums1.length;
        Arrays.sort(nums1);
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(nums2[a], nums2[b]));
        int[] ans = new int[n];
        int lo = 0, hi = n - 1;
        for (int x : nums1) {
            if (x > nums2[order[lo]]) {
                ans[order[lo++]] = x;
            } else {
                ans[order[hi--]] = x;
            }
        }
        return ans;
    }
}

var advantageCount = function(nums1, nums2) {
    const n = nums1.length;
    nums1.sort((a, b) => a - b);
    const order = Array.from({ length: n }, (_, i) => i).sort((a, b) => nums2[a] - nums2[b]);
    const ans = new Array(n);
    let lo = 0, hi = n - 1;
    for (const x of nums1) {
        if (x > nums2[order[lo]]) {
            ans[order[lo++]] = x;
        } else {
            ans[order[hi--]] = x;
        }
    }
